SELECT r.id, r.referral_code, r.patient_name, r.gender, r.age, r.phone, r.symptoms, r.medical_history, r.reason, r.refer_advice, r.source_type, r.target_type, r.target_dept_id, r.target_dept_name, r.target_hospital_name, r.status, r.registration_record_id, rr.registration_no, rr.visit_time, rr.patient_id, r.original_dept_id, r.original_dept_name, r.original_doctor_id, r.original_doctor_name, r.apply_time, r.review_time, r.cancel_time, r.auto_register_status FROM hospital_referral r LEFT JOIN registration_record rr ON r.registration_record_id = rr.record_id
AND r.patient_name LIKE CONCAT('%', #{patientName}, '%')
AND r.phone LIKE CONCAT('%', #{phone}, '%')
AND r.referral_code = #{referralCode}
AND r.status = #{status}
AND r.source_type = #{sourceType}
AND r.target_type = #{targetType}
AND DATE(r.apply_time) >= #{startDate}
AND DATE(r.apply_time) <= #{endDate}
ORDER BY r.create_time DESC LIMIT #{startIndex}, #{pageSize}

SELECT 
    COUNT(*)
FROM 
    hospital_referral r
LEFT JOIN 
    registration_record rr ON r.registration_record_id = rr.record_id


        AND r.patient_name LIKE CONCAT('%', #{patientName}, '%')


        AND r.phone LIKE CONCAT('%', #{phone}, '%')


